#include <iostream>
using namespace std;

const int MAXN = 100001;
long long tree[4 * MAXN];
int a[MAXN];
int n;

void build(int p, int l, int r) {
    if (l == r) {
        tree[p] = a[l];
        return;
    }
    int mid = (l + r) >> 1;
    build(p << 1, l, mid);
    build(p << 1 | 1, mid + 1, r);
    tree[p] = tree[p << 1] + tree[p << 1 | 1];
}

void update(int p, int l, int r, int pos, int val) {
    if (l == r) {
        tree[p] = val;
        return;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid) update(p << 1, l, mid, pos, val);
    else update(p << 1 | 1, mid + 1, r, pos, val);
    tree[p] = tree[p << 1] + tree[p << 1 | 1];
}

long long query(int p, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return tree[p];
    int mid = (l + r) >> 1;
    long long sum = 0;
    if (ql <= mid) sum += query(p << 1, l, mid, ql, qr);
    if (qr > mid) sum += query(p << 1 | 1, mid + 1, r, ql, qr);
    return sum;
}

int main() {
    int m;
    cin >> n >> m;
    for (int i = 1; i <= n; i++) cin >> a[i];
    build(1, 1, n);
    while (m--) {
        int op, x, y;
        cin >> op >> x >> y;
        if (op == 1) update(1, 1, n, x, y);
        else cout << query(1, 1, n, x, y) << endl;
    }
    return 0;
}

units.explanation:
懒标记（Lazy Tag）是线段树实现区间修改的核心技巧。

问题：如果对 [1, n] 每个元素都加 v，逐个修改需要 O(n log n)，太慢。

核心思想：延迟更新。修改一个区间时，如果当前节点对应的区间完全被覆盖，只修改当前节点并打上标记，不再递归到子节点。等将来需要访问子节点时，再把标记下传（pushdown）。

pushdown 操作：
void pushdown(int p, int l, int r) {
    if (lazy[p] != 0) {
        int mid = (l + r) / 2;
        // 下传给左儿子
        tree[2*p] += lazy[p] * (mid - l + 1);
        lazy[2*p] += lazy[p];
        // 下传给右儿子
        tree[2*p+1] += lazy[p] * (r - mid);
        lazy[2*p+1] += lazy[p];
        // 清除当前标记
        lazy[p] = 0;
    }
}

关键理解：
- lazy[p] 表示节点 p 对应的区间内每个元素还要加的值
- tree[p] 始终维护的是正确的区间和（已经算上了 lazy 的影响）
- pushdown 在每次访问子节点前调用
- 区间长度要乘到 tree 的更新中：tree[p] += lazy[p] * (r - l + 1)

有了懒标记，区间修改和区间查询都变成了 O(log n)。

