    if (lazy[p]) {
        int mid = (l + r) >> 1;
        tree[p << 1] += lazy[p] * (mid - l + 1);
        lazy[p << 1] += lazy[p];
        tree[p << 1 | 1] += lazy[p] * (r - mid);
        lazy[p << 1 | 1] += lazy[p];
        lazy[p] = 0;
