#include <iostream>
#include <algorithm>
using namespace std;

const int MAXN = 100001;
const int INF = 2e9;
int tree[4 * MAXN], lazy[4 * MAXN];
int a[MAXN];
int n;

void build(int p, int l, int r) {
    if (l == r) { tree[p] = a[l]; return; }
    int mid = (l + r) >> 1;
    build(p << 1, l, mid);
    build(p << 1 | 1, mid + 1, r);
    tree[p] = max(tree[p << 1], tree[p << 1 | 1]);
}

void pushdown(int p) {
    if (lazy[p]) {
        tree[p << 1] += lazy[p];
        lazy[p << 1] += lazy[p];
        tree[p << 1 | 1] += lazy[p];
        lazy[p << 1 | 1] += lazy[p];
        lazy[p] = 0;
    }
}

void update(int p, int l, int r, int ul, int ur, int val) {
    if (ul <= l && r <= ur) {
        tree[p] += val;
        lazy[p] += val;
        return;
    }
    pushdown(p);
    int mid = (l + r) >> 1;
    if (ul <= mid) update(p << 1, l, mid, ul, ur, val);
    if (ur > mid) update(p << 1 | 1, mid + 1, r, ul, ur, val);
    tree[p] = max(tree[p << 1], tree[p << 1 | 1]);
}

int query(int p, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return tree[p];
    pushdown(p);
    int mid = (l + r) >> 1;
    int res = -INF;
    if (ql <= mid) res = max(res, query(p << 1, l, mid, ql, qr));
    if (qr > mid) res = max(res, query(p << 1 | 1, mid + 1, r, ql, qr));
    return res;
}

