#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MAXN = 100001;
int cover[4 * MAXN];
long long len[4 * MAXN];
vector<long long> ys;
int cnt;

struct Event {
    long long x, y1, y2;
    int type;
};

void pushup(int p, int l, int r) {
    if (cover[p] > 0) {
        len[p] = ys[r] - ys[l];
    } else if (l + 1 == r) {
        len[p] = 0;
    } else {
        len[p] = len[p << 1] + len[p << 1 | 1];
    }
}

void update(int p, int l, int r, int ul, int ur, int val) {
    if (ul <= l && r <= ur) {
        cover[p] += val;
        pushup(p, l, r);
        return;
    }
    if (l + 1 == r) return;
    int mid = (l + r) >> 1;
    if (ul < mid) update(p << 1, l, mid, ul, ur, val);
    if (ur > mid) update(p << 1 | 1, mid, r, ul, ur, val);
    pushup(p, l, r);
}

int main() {
    int n;
    cin >> n;
    vector<Event> events;
    for (int i = 0; i < n; i++) {
        long long x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        events.push_back({x1, y1, y2, 1});
        events.push_back({x2, y1, y2, -1});
        ys.push_back(y1);
        ys.push_back(y2);
    }
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    cnt = ys.size();
    auto getId = [&](long long y) {
        return lower_bound(ys.begin(), ys.end(), y) - ys.begin();
    };
    sort(events.begin(), events.end(),
         [](const Event& a, const Event& b) { return a.x < b.x; });
    long long ans = 0;
    for (int i = 0; i < (int)events.size(); i++) {
        if (i > 0) ans += len[1] * (events[i].x - events[i - 1].x);
        int y1 = getId(events[i].y1);
        int y2 = getId(events[i].y2);
        update(1, 0, cnt - 1, y1, y2, events[i].type);
    }
    cout << ans << endl;
    return 0;
}
